export function renderAsciiLetters(text, width, height, rows) {
    const out = [];
    const normalized = text.toUpperCase();
    for (let r = 0; r < height; r++) {
        let line = '';
        for (const c of normalized) {
            const pos = /^[A-Z]$/.test(c) ? c.charCodeAt(0) - 65 : 26;
            line += rows[r].slice(pos * width, (pos + 1) * width);
        }
        out.push(line);
    }
    return out;
}
